  "Why you match": { tamil: "நீங்கள் ஏன் தகுதியானவர்", telugu: "మీరు ఎందుకు సరిపోతారు", hindi: "आपकी पात्रता का कारण", malayalam: "നിങ്ങൾക്ക് യോജിക്കുന്നതെന്തുകൊണ്ട്" },
  "Requirements not met": { tamil: "பூர்த்தி செய்யப்படாத தேவைகள்", telugu: "పూర్తి కాని అవసరాలు", hindi: "पूरी न हुई शर्तें", malayalam: "പൂർത്തിയാകാത്ത ആവശ്യങ്ങൾ" },
  "What still needs verification": { tamil: "இன்னும் சரிபார்க்க வேண்டியது", telugu: "ఇంకా ధృవీకరించాల్సినవి", hindi: "अभी क्या सत्यापित करना है", malayalam: "ഇനിയും പരിശോധിക്കേണ്ടത്" },
  "Official source:": { tamil: "அதிகாரப்பூர்வ ஆதாரம்:", telugu: "అధికారిక మూలం:", hindi: "आधिकारिक स्रोत:", malayalam: "ഔദ്യോഗിക ഉറവിടം:" },
  "Government source": { tamil: "அரசு ஆதாரம்", telugu: "ప్రభుత్వ మూలం", hindi: "सरकारी स्रोत", malayalam: "സർക്കാർ ഉറവിടം" },
  "AI assessment": { tamil: "AI மதிப்பீடு", telugu: "AI అంచనా", hindi: "AI आकलन", malayalam: "AI വിലയിരുത്തൽ" },
  "Sources checked": { tamil: "சரிபார்க்கப்பட்ட ஆதாரங்கள்", telugu: "తనిఖీ చేసిన మూలాలు", hindi: "जाँचे गए स्रोत", malayalam: "പരിശോധിച്ച ഉറവിടങ്ങൾ" },
  "This assessment is based on information retrieved from government sources. Final eligibility is determined by the relevant government department.": { tamil: "இந்த மதிப்பீடு அரசு ஆதாரங்களிலிருந்து பெறப்பட்ட தகவலின் அடிப்படையிலானது. இறுதித் தகுதியை சம்பந்தப்பட்ட அரசு துறை தீர்மானிக்கும்.", telugu: "ఈ అంచనా ప్రభుత్వ వనరుల నుంచి పొందిన సమాచారంపై ఆధారపడింది. తుది అర్హతను సంబంధిత ప్రభుత్వ శాఖ నిర్ణయిస్తుంది.", hindi: "यह आकलन सरकारी स्रोतों से मिली जानकारी पर आधारित है। अंतिम पात्रता संबंधित सरकारी विभाग तय करेगा।", malayalam: "ഈ വിലയിരുത്തൽ സർക്കാർ ഉറവിടങ്ങളിൽ നിന്നുള്ള വിവരങ്ങളെ അടിസ്ഥാനമാക്കിയുള്ളതാണ്. അന്തിമ യോഗ്യത ബന്ധപ്പെട്ട സർക്കാർ വകുപ്പ് തീരുമാനിക്കും." },
  "Upload or provide only the requirements for the scheme you selected.": { tamil: "நீங்கள் தேர்ந்தெடுத்த திட்டத்திற்குத் தேவையானவற்றை மட்டும் பதிவேற்றவும் அல்லது வழங்கவும்.", telugu: "మీరు ఎంచుకున్న పథకానికి అవసరమైన వాటిని మాత్రమే అప్‌లోడ్ చేయండి లేదా అందించండి.", hindi: "आपने जो योजना चुनी है, उसी की ज़रूरतें अपलोड करें या दें।", malayalam: "തിരഞ്ഞെടുത്ത പദ്ധതിക്ക് ആവശ്യമായവ മാത്രം അപ്‌ലോഡ് ചെയ്യുകയോ നൽകുകയോ ചെയ്യുക." },
  "Does this requirement apply to you?": { tamil: "இந்தத் தேவை உங்களுக்குப் பொருந்துமா?", telugu: "ఈ అవసరం మీకు వర్తిస్తుందా?", hindi: "क्या यह शर्त आप पर लागू होती है?", malayalam: "ഈ നിബന്ധന നിങ്ങൾക്ക് ബാധകമാണോ?" },
  "Choose an answer": { tamil: "ஒரு பதிலைத் தேர்ந்தெடுக்கவும்", telugu: "సమాధానాన్ని ఎంచుకోండి", hindi: "एक जवाब चुनें", malayalam: "ഒരു ഉത്തരം തിരഞ്ഞെടുക്കുക" },
