  "No file upload required": { tamil: "கோப்பைப் பதிவேற்றத் தேவையில்லை", telugu: "ఫైల్ అప్‌లోడ్ అవసరం లేదు", hindi: "फ़ाइल अपलोड करने की ज़रूरत नहीं", malayalam: "ഫയൽ അപ്‌ലോഡ് ആവശ്യമില്ല" },
  "This requirement should be entered or provided as information during the application process.": { tamil: "விண்ணப்பத்தின் போது இந்தத் தகவலை உள்ளிடவும் அல்லது வழங்கவும்.", telugu: "దరఖాస్తు సమయంలో ఈ సమాచారాన్ని నమోదు చేయండి లేదా అందించండి.", hindi: "आवेदन के दौरान यह जानकारी दर्ज करें या दें।", malayalam: "അപേക്ഷിക്കുമ്പോൾ ഈ വിവരം നൽകുകയോ രേഖപ്പെടുത്തുകയോ ചെയ്യുക." },
  "Conditional requirement": { tamil: "நிபந்தனைக்குட்பட்ட தேவை", telugu: "షరతుతో కూడిన అవసరం", hindi: "शर्त के अनुसार ज़रूरी", malayalam: "വ്യവസ്ഥാപിത ആവശ്യം" },
  "This requirement only applies when the stated condition is applicable to your case.": { tamil: "குறிப்பிட்ட நிபந்தனை உங்கள் நிலைக்குப் பொருந்தும்போது மட்டுமே இது தேவை.", telugu: "పేర్కొన్న షరతు మీ పరిస్థితికి వర్తించినప్పుడు మాత్రమే ఇది అవసరం.", hindi: "बताई गई शर्त आपकी स्थिति पर लागू होने पर ही यह ज़रूरी है।", malayalam: "പറഞ്ഞിരിക്കുന്ന വ്യവസ്ഥ നിങ്ങളുടെ സാഹചര്യത്തിന് ബാധകമാണെങ്കിൽ മാത്രമേ ഇത് ആവശ്യമുള്ളൂ." },
