for (const [source, translations] of Object.entries(COMMON_TRANSLATIONS)) {
  for (const [language, translated] of Object.entries(translations)) {
    DICTIONARIES[language][source] = translated;
  }
}

const ATTRIBUTES = ["placeholder", "title", "aria-label"];

export function translateText(text, language) {
  const dictionary = DICTIONARIES[language];
  if (!dictionary || !text.trim()) return text;
  const key = text.replace(/\s+/g, " ").trim();
  const languageOrder = { tamil: 0, telugu: 1, hindi: 2, malayalam: 3 };
  const translation = dictionary[key] || REGION_NAMES[key]?.[languageOrder[language]];
  let localized = translation;
  if (!localized) {
    const templates = {
      kannada: { min: "ಕನಿಷ್ಠ ವಯಸ್ಸು {n} ವರ್ಷ", max: "ಗರಿಷ್ಠ ವಯಸ್ಸು {n} ವರ್ಷ", income: "ಆದಾಯ ₹{n} ಅಥವಾ ಅದಕ್ಕಿಂತ ಕಡಿಮೆ ಇರಬೇಕು", states: "ಯೋಜನೆ ಈ ರಾಜ್ಯಗಳಲ್ಲಿ ಲಭ್ಯವಿದೆ: {n}" },
      tamil: { min: "குறைந்தபட்ச வயது {n} ஆண்டுகள்", max: "அதிகபட்ச வயது {n} ஆண்டுகள்", income: "வருமானம் ₹{n} அல்லது அதற்குக் குறைவாக இருக்க வேண்டும்", states: "இந்த மாநிலங்களில் திட்டம் கிடைக்கும்: {n}" },
      telugu: { min: "కనీస వయస్సు {n} సంవత్సరాలు", max: "గరిష్ఠ వయస్సు {n} సంవత్సరాలు", income: "ఆదాయం ₹{n} లేదా అంతకంటే తక్కువగా ఉండాలి", states: "ఈ రాష్ట్రాల్లో పథకం అందుబాటులో ఉంది: {n}" },
      hindi: { min: "न्यूनतम आयु {n} वर्ष", max: "अधिकतम आयु {n} वर्ष", income: "आय ₹{n} या उससे कम होनी चाहिए", states: "इन राज्यों में योजना उपलब्ध है: {n}" },
      malayalam: { min: "കുറഞ്ഞ പ്രായം {n} വയസ്സ്", max: "പരമാവധി പ്രായം {n} വയസ്സ്", income: "വരുമാനം ₹{n} അല്ലെങ്കിൽ അതിൽ കുറവായിരിക്കണം", states: "ഈ സംസ്ഥാനങ്ങളിൽ പദ്ധതി ലഭ്യമാണ്: {n}" },
    }[language];
    let match = key.match(/^Minimum age is (\d+)$/i);
    if (match && templates) localized = templates.min.replace("{n}", match[1]);
    match = key.match(/^Maximum age is (\d+)$/i);
    if (!localized && match && templates) localized = templates.max.replace("{n}", match[1]);
    match = key.match(/^Income must be ₹([\d,]+) or below$/i);
    if (!localized && match && templates) localized = templates.income.replace("{n}", match[1]);
    match = key.match(/^Scheme is available in: (.+)$/i);
    if (!localized && match && templates) localized = templates.states.replace("{n}", match[1]);
  }
  if (!localized) return text;
  const leading = text.match(/^\s*/)?.[0] || "";
  const trailing = text.match(/\s*$/)?.[0] || "";
  return `${leading}${localized}${trailing}`;
}

function translateNode(node, language) {
  if (typeof node === "string") return translateText(node, language);
  if (Array.isArray(node)) return node.map((child) => translateNode(child, language));
  if (!isValidElement(node)) return node;

  const props = { ...node.props };
  for (const attribute of ATTRIBUTES) {
    if (typeof props[attribute] === "string") {
      props[attribute] = translateText(props[attribute], language);
    }
  }
  if (props.children !== undefined) {
    props.children = translateNode(props.children, language);
  }
  return cloneElement(node, props);
}

export default function TranslateTree({ language, children }) {
  return translateNode(children, language);
}
